import{_ as a,H as p,f as n,i}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"04 | 移动平台的视频渲染（一）：OpenGLES基础","description":"","frontmatter":{},"headers":[{"level":2,"title":"视频渲染技术选型","slug":"视频渲染技术选型","link":"#视频渲染技术选型","children":[{"level":3,"title":"平台上层的 API","slug":"平台上层的-api","link":"#平台上层的-api","children":[]},{"level":3,"title":"跨平台的 OpenGL ES","slug":"跨平台的-opengl-es","link":"#跨平台的-opengl-es","children":[]},{"level":3,"title":"平台提供的最新技术","slug":"平台提供的最新技术","link":"#平台提供的最新技术","children":[]}]},{"level":2,"title":"OpenGL ES","slug":"opengl-es","link":"#opengl-es","children":[{"level":3,"title":"上下文环境","slug":"上下文环境","link":"#上下文环境","children":[]},{"level":3,"title":"OpenGL（ES）的用途","slug":"opengl-es-的用途","link":"#opengl-es-的用途","children":[]},{"level":3,"title":"OpenGL 渲染管线","slug":"opengl-渲染管线","link":"#opengl-渲染管线","children":[]},{"level":3,"title":"创建显卡执行程序","slug":"创建显卡执行程序","link":"#创建显卡执行程序","children":[]},{"level":3,"title":"创建 Shader","slug":"创建-shader","link":"#创建-shader","children":[]},{"level":3,"title":"创建 Program","slug":"创建-program","link":"#创建-program","children":[]}]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"快手·移动端音视频开发实战/04｜移动平台的视频渲染（一）：OpenGLES基础.md","filePath":"快手·移动端音视频开发实战/04｜移动平台的视频渲染（一）：OpenGLES基础.md","lastUpdated":1795563308000}'),s={name:"快手·移动端音视频开发实战/04｜移动平台的视频渲染（一）：OpenGLES基础.md"};function t(l,e,r,o,h,d){return p(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="_04-移动平台的视频渲染-一-opengles基础" tabindex="-1">04 | 移动平台的视频渲染（一）：OpenGLES基础 <a class="header-anchor" href="#_04-移动平台的视频渲染-一-opengles基础" aria-label="Permalink to &quot;04 | 移动平台的视频渲染（一）：OpenGLES基础&quot;">​</a></h1><p>你好，我是展晓凯。今天我们来学习移动平台的视频渲染。</p><p>虽然我们的主题是视频渲染，但严格来讲其实是视频画面（不包含声音）的渲染。在音视频领域的大部分经典场景是离不开画面的渲染的，比如：视频播放器、视频编辑器、短视频录制、贴纸以及礼物的渲染等等，所以掌握视频画面渲染技术的重要性是不言而喻的。那视频渲染都有哪些技术可用呢？最常用的是哪一种呢？带着这些问题，让我们一起开始本节课的学习吧！</p><p>注意，这里我们所说的渲染并不单单指的是直接绘制到系统屏幕上，一些高级处理操作，比如滤镜、磨皮、瘦脸、贴纸等，也是渲染的一部分。</p><h2 id="视频渲染技术选型" tabindex="-1">视频渲染技术选型 <a class="header-anchor" href="#视频渲染技术选型" aria-label="Permalink to &quot;视频渲染技术选型&quot;">​</a></h2><p>在开始学习移动平台的视频渲染技术之前，我们先探讨一下，渲染的源头是什么？前两节课我们一起学习了音频的渲染源是 PCM 数据，而视频的渲染源是 YUV 或者 RGBA 格式的数据，这种数据是描述画面最基础的格式，其中 YUV 常用在视频的原始格式中，RGBA 常用在一些图像的原始格式上。</p><p>目前各个平台最终渲染到屏幕上的都是 RGBA 格式的，因为硬件对屏幕上的设计就是按照每个像素点分为四个子像素来实现的，所以 YUV 和 RGBA 之间是可以互相转换的。我们最终的实战案例是视频播放器，所以这节课我们重点学习的是如何将 YUV 数据渲染出来，在移动平台上都有哪些落地方案。</p><h3 id="平台上层的-api" tabindex="-1">平台上层的 API <a class="header-anchor" href="#平台上层的-api" aria-label="Permalink to &quot;平台上层的 API&quot;">​</a></h3><p>Android 平台在 SDK 层提供了 Canvas 和 Paint 的 API 接口，便于开发者将位图（Bitmap）绘制到系统的屏幕上，常用于一些复杂的自定义 View 的实现，也可以再结合 SurfaceView 或者 TexureView，将绘制线程从主线程中独立出来进行渲染，满足基本的绘图实现。</p><p>iOS 平台的 SDK 层也提供了 Quartz 2D 把位图（Bitmap）绘制到屏幕上，在一些自定义View 以及获取 snapshot 的场景下使用。这种方式的优点是各自平台的开发者使用起来非常简单，无需了解更深层次的绘图原理就能做一些简单的图形图像处理，也可以利用系统提供的一些 API 进行各种变换、阴影以及渐变的处理。缺点也比较明显，需要各个平台独立书写自己平台代的码进行渲染绘制，并且当需要一些高级处理和更高性能的时候，就会捉襟见肘，比如视频的美颜、跟脸贴纸以及一些视频编辑的处理等。</p><h3 id="跨平台的-opengl-es" tabindex="-1">跨平台的 OpenGL ES <a class="header-anchor" href="#跨平台的-opengl-es" aria-label="Permalink to &quot;跨平台的 OpenGL ES&quot;">​</a></h3><p>在移动设备上，各个平台提供了更加底层的图形绘制接口，就是众所周知的 OpenGL ES。它天生就是为了跨平台而设计的，在跨平台方面具有独特的优势，由于是最底层的图形绘制接口，所以在性能以及图形的高级处理方面也都没有任何问题。缺点其实也很明显，就是掌握这项技术的学习成本是比较高的，不单单要了解 OpenGL ES 的各种概念，并且还要为不同平台创建自己的上下文环境，同时还得掌握 OpenGL 自己的编程语言 GLSL 的语法和运行机制。</p><h3 id="平台提供的最新技术" tabindex="-1">平台提供的最新技术 <a class="header-anchor" href="#平台提供的最新技术" aria-label="Permalink to &quot;平台提供的最新技术&quot;">​</a></h3><p>Android 在 10.0 系统之后开始支持 Vulkan，Vulkan 是用于高性能 3D 渲染的渲染方法，是Khronos Group 组织开发的新一代 API，用于替换掉 OpenGL，所以天生也是跨平台的，支持Windows、Linux、Android，还有 iOS 和 Mac 平台，只不过在 iOS 平台上底层是 MoltenVK来实现的。</p><p>由于这项渲染技术是 OpenGL 的下一代，所以渲染性能方面是非常好的，并且在模块化角度也更好一些。但是有两个缺点，一是对现有的渲染系统做大规模的迁移，没有特别友好的方案；另外一个就是对于普通的开发人员来讲，上手难度比较高。但总的来说，未来它将成为用于专业图形图像渲染引擎的底层技术。</p><p>同样 iOS 平台提供了 Metal 来作为 OpenGL 的替代者，在 iOS12 系统之后弃用 OpenGLES，系统的一些框架全面改成默认 Metal 支持。由于 Metal 的设计和 OpenGL 比较类似，开发者上手难度并不大，绘制性能也有比较明显的提升，主要缺点是跨平台性比较差。</p><p>刚刚我们也提到了，渲染并不单单是要把画面绘制到屏幕上，更多的是需要构建一个跨平台、可扩展、高性能的渲染引擎。这对于后续的一些处理是非常关键的，最终我们选择的技术依然是 OpenGL ES，虽然它上手难度会大一些，但是通过接下来的学习，我会带你彻底掌握这项技术，让我们一起来进入 OpenGL ES 的新世界吧！</p><h2 id="opengl-es" tabindex="-1">OpenGL ES <a class="header-anchor" href="#opengl-es" aria-label="Permalink to &quot;OpenGL ES&quot;">​</a></h2><p>OpenGL 的全称是 Open Graphics Library，它用于二维或三维图像的处理与渲染，是一个功能强大、调用方便的底层图形库。它定义了一套跨编程语言、跨平台编程的专业图形程序接口。而 OpenGL ES（OpenGL for Embedded Systems）是它在嵌入式设备上的版本，这个版本是针对智能手机等嵌入式设备设计的，可以理解为是 Open GL 的一个子集。</p><p>目前，OpenGL 的最新版本已经达到了 3.0 以上，由于兼容性以及现存渲染系统的架构，目前OpenGL ES 2.0 还是使用最广泛的版本。所以我们就在 2.0 版本的基础上进行编程，来实现图像的处理与渲染。由于在视频应用这一场景下，绝大部分都是使用二维图像的处理与渲染，所以这里我们只讨论 OpenGL ES 的二维部分的内容，不涉及三维部分的介绍。其实除了专业的引擎开发者，大部分应用开发者只需要有二维部分的知识就可以完成我们的绝大部分工作了。</p><h3 id="上下文环境" tabindex="-1">上下文环境 <a class="header-anchor" href="#上下文环境" aria-label="Permalink to &quot;上下文环境&quot;">​</a></h3><p>由于 OpenGL 是基于跨平台设计的，所以每个平台需要自己提供渲染的基础实现，用来抹平各个系统本身的差异。就像我们常说 Java 语言是跨平台的，实际上是 JVM 抹平了各个平台的差异一样。每个平台提供渲染的基础实现，我们称之为 OpenGL 的上下文环境。另外在OpenGL 的设计中，OpenGL 是不负责管理窗口的，窗口的管理也交由每个平台自己来完成。与上下文环境一样，窗口管理在每个平台也都有自己的实现。</p><p>具体来讲，作为 OpenGL ES 的上下文环境，iOS 平台为开发者提供了 EAGL，而 Android 平台（Linux 平台）为开发者提供了 EGL。所以如果想要让 OpenGL 程序运行在多个平台上，也要学会利用各个平台提供的 API 接口，为 OpenGL ES 创建出上下文环境。</p><p>除了了解 OpenGL ES 的各种上下文环境，这里我们还需要知道一个开源的跨平台多媒体开发库——SDL，它给开发人员提供了面向 SDL 的 API 编程，能够通过交叉编译这个库解决多平台下需要手动构建 OpenGL 上下文环境以及窗口管理的问题。但在移动端，这样的实现会让我们失去一部分更加灵活的控制，导致一些场景下的功能不能实现。因此我们这里不使用SDL，而是通过裸用各个平台的 API 来构建 OpenGL 的上下文环境。</p><p>上面介绍了 OpenGL（ES）是什么以及它的上下文环境，下面我们一起来看一下用 OpenGL（ES）能做什么。</p><h3 id="opengl-es-的用途" tabindex="-1">OpenGL（ES）的用途 <a class="header-anchor" href="#opengl-es-的用途" aria-label="Permalink to &quot;OpenGL（ES）的用途&quot;">​</a></h3><p>刚刚我们也提到了 OpenGL（ES）是做图形图像处理的库，尤其运行在移动设备上，它有更好的性能与绘制效果。</p><p>要想了解 OpenGL ES 能做什么，就不得不提到一个开源项目——GPUImage。它的实现非常优雅、完备，尤其是在 iOS 平台，提供了视频录制、视频编辑、离线保存这些场景。</p><p>其中很重要的一部分就是内部滤镜的实现，在里面我们可以找到大部分图形图像处理 Shader的实现，包括：</p><ul><li><p>基础的图像处理算法：饱和度、对比度、亮度、色调曲线、灰度、白平衡等；</p></li><li><p>图像像素处理的实现：锐化、高斯模糊等；</p></li><li><p>视觉效果的实现：素描、卡通、浮雕效果等；</p></li><li><p>各种混合模式的实现。</p></li></ul><p>除此之外，开发者也可以自己去实现美颜滤镜效果、瘦脸效果以及粒子效果等等。</p><p>GPUImage 框架是使用 OpenGL ES 中的 GLSL 书写出了上述的各种 Shader。GLSL（OpenGL Shading Language）是 OpenGL 的着色器语言，也是 2.0 版本中最出色的功能。开发人员可以使用这种语言编写程序运行在 GPU 上来进行图像处理或渲染。使用 GLSL 写的代码最终可以编译、链接成为一个 GLProgram。</p><ul><li>注：Graphic Processor Unit 是图形图像处理单元，可以把它理解成一种高并发的运算器。</li></ul><p>一个 GLProgram 分为两部分，一是顶点着色器（Vertex Shader），二是片元着色器（Fragment Shader），这两部分分别完成各自在 OpenGL 渲染管线中的功能。那它们是怎么工作的呢？我们一起来看一下。</p><h3 id="opengl-渲染管线" tabindex="-1">OpenGL 渲染管线 <a class="header-anchor" href="#opengl-渲染管线" aria-label="Permalink to &quot;OpenGL 渲染管线&quot;">​</a></h3><p>如果想要了解着色器并理解它们的工作机制，就要对 OpenGL 的渲染管线有深入的了解。在学习之前，我们还是先来了解几个概念。我们平时说的点、直线、三角形都是几何图元，是在顶点着色器中指定的，用这些几何图元创建的物体叫做模型，而根据这些模型创建并显示图像的过程就是我们所说的渲染。在渲染过程结束之后，图像就会以像素点的形式绘制到屏幕上了。</p><p>一张 RGBA 格式的图像在内存中是这样描述的：每四个 Byte 表示一个像素点的 RGBA 的数据，这些像素点可以被组织成一个大的一维数组，用来在内存中表述这张图片。那在显存中如何描述呢？</p><p>在显存中，这些像素点被组织成帧缓冲区（framebuffer），帧缓冲区保存了显卡为了控制屏幕上所有像素的颜色以及强度所需要的全部信息。理解了帧缓冲区的概念，接下来我们就可以进入 OpenGL 渲染管线的学习了，这个部分是学会使用 OpenGL 非常重要的环节。</p><p>OpenGL 的渲染管线具体是指什么呢？其实就是 OpenGL 引擎把图像（内存中的 RGBA 数据）一步步渲染到屏幕上去的步骤。渲染管线主要分为以下几个阶段：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E7%A7%BB%E5%8A%A8%E7%AB%AF%E9%9F%B3%E8%A7%86%E9%A2%91%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E7%A7%BB%E5%8A%A8%E7%AB%AF%E9%9F%B3%E8%A7%86%E9%A2%91%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/1.png" alt=""></a></p><ul><li>图1 OpenGL的渲染管线</li></ul><p>阶段一：指定几何对象</p><p>几何对象，就是刚才我们说的几何图元，这里 OpenGL 引擎会根据开发者的指令去绘制几何图元。OpenGL（ES）提供给开发者的绘制方法 glDrawArrays 的第一个参数 mode，就是指定绘制方式。绘制方式的可选值有点、线、三角形三种，分别应用于不同的场景中。</p><p>粒子效果的场景中，我们一般用点（GL_POINTS）来绘制；直线的场景中，我们主要用线（GL_LINES）来绘制；所有二维图形图像的渲染，都用三角形（GL_TRIANGLE_STRIP）来绘制。</p><p>我们根据不同的场景选择的绘制方式，就决定了 OpenGL（ES）渲染管线的第一阶段怎么去绘制几何图元。</p><p>阶段二：顶点变换</p><p>不论阶段一指定的是哪种几何对象，所有的几何数据都要来到顶点处理阶段，顶点处理阶段的操作就是变换顶点的位置：一是根据模型视图和投影矩阵的计算来改变物体（顶点）坐标的位置；二是根据纹理坐标与纹理矩阵来改变纹理坐标的位置。这里的输出是用 gl_Position 来表示具体的顶点位置的，如果是用点（GL_POINTS）来绘制几何图元的话，还应该输出gl_PointSize。</p><p>如果涉及三维的渲染，这里还会处理光照计算和法线变换，因为这节课不会涉及三维图像的渲染，所以这里不做过多介绍。</p><p>阶段三：图元组装</p><p>在阶段二的时候，我们已经确定了物体坐标和顶点坐标，然后到这个阶段进行图元组装。这里我们根据应用程序送往图元的规则（如 GL_POINTS 、GL_TRIANGLES 等）以及具体的纹理坐标，把纹理组装成图元。</p><p>阶段四：栅格化操作</p><p>由上一阶段传递过来的图元数据，在这里会被分解成更小的单元并对应帧缓冲区的各个像素。这些单元叫做“片元”，一个片元可能包含窗口颜色、纹理坐标等属性。片元的属性则是图元上顶点数据经过插值而确定的，这其实就是栅格化操作，这个操作能够确定每一个片元是什么。</p><p>阶段五：片元处理</p><p>通过纹理坐标取得纹理中相对应的片元像素值，根据自己的需要改变这个片元，比如调节饱和度、锐化等，最终输出的是一个四维向量 gl_FragColor，我们用它来表示修改之后的片元像素。</p><p>阶段六：帧缓冲操作</p><p>帧缓冲操作是渲染管线的最后一个阶段，执行帧缓冲的写入等操作，OpenGL 引擎负责把最终的像素值写入到帧缓冲区中。</p><p>这就是 OpenGL 渲染管线的六个步骤，从指定几何图元到帧缓冲区写入像素，图像就被OpenGL 引擎一步步地渲染到屏幕（FBO）上去了。</p><p>还记得我们之前提到过，OpenGL ES 2.0 版本与之前的版本相比，最出色的功能就是开发者能够编写着色器来完成渲染管线的某个阶段。这里的“某个阶段”，实际上就是顶点变换阶段和片元处理阶段。开发者可以使用顶点着色器自己完成顶点变换阶段；也能使用片元（像素）着色器来完成片元处理阶段。</p><p>具体该如何书写顶点着色器和片元着色器呢？在专栏的第 6 讲我会详细地讲解 GLSL 语法以及内嵌函数，在这里先假设我们已经书写好了顶点着色器和片元着色器，现在需要通过OpenGL ES 提供给开发者的接口来创建显卡可执行程序了。</p><h3 id="创建显卡执行程序" tabindex="-1">创建显卡执行程序 <a class="header-anchor" href="#创建显卡执行程序" aria-label="Permalink to &quot;创建显卡执行程序&quot;">​</a></h3><p>假如我们已经完成了一组 Shader 的实例。那如何让显卡来运行这一组 Shader 呢？或者说如何用我们的 Shader 来替换掉 OpenGL 渲染管线中的那两个阶段呢？下面我们就来学习一下如何把 Shader 扔给 OpenGL 的渲染管线，这一部分叫做接口程序部分，就是利用 OpenGL 提供的接口来驱动 OpenGL 进行渲染。我们先来看一下图 2，它描述了如何创建一个显卡的可执行程序（Program）。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E7%A7%BB%E5%8A%A8%E7%AB%AF%E9%9F%B3%E8%A7%86%E9%A2%91%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E7%A7%BB%E5%8A%A8%E7%AB%AF%E9%9F%B3%E8%A7%86%E9%A2%91%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/2.png" alt=""></a></p><ul><li>图2 创建显卡可执行程序流程图</li></ul><p>根据图示，我们来看一看如何一步步地创建出这个 Program。首先看图的右半部分，也就是创建 Shader 的过程。</p><h3 id="创建-shader" tabindex="-1">创建 Shader <a class="header-anchor" href="#创建-shader" aria-label="Permalink to &quot;创建 Shader&quot;">​</a></h3><p>第一步是调用 glCreateShader 方法创建一个对象，作为 Shader 的容器，这个函数返回一个容器的句柄，函数原型如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GLuint glCreateShader(GLenum shaderType);</span></span></code></pre></div><p>函数原型中的参数 shaderType 有两种类型：</p><ul><li><p>一是 GL_VERTEX_SHADER，创建顶点着色器时开发者应传入的类型；</p></li><li><p>二是 GL_FRAGMENT_SHADER，创建片元着色器时开发者应传入的类型。</p></li></ul><p>第二步就是给创建的这个 Shader 添加源代码，对应图片最右边的两个 Shader Content，它们就是根据 GLSL 语法和内嵌函数书写出来的两个着色器程序，都是字符串类型。这个函数的作用就是把开发者的着色器程序加载到着色器句柄所关联的内存中，函数原型如下：</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> glShaderSource</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(GLuint shader, int numOfStrings, const char </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">strings, int</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">       *</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lenOfStrings)</span></span></code></pre></div><p>最后一步就是来编译这个 Shader，编译 Shader 的函数原型如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void glCompileShader(GLuint shader);</span></span></code></pre></div><p>编译完成之后，怎么知道这个 Shader 被编译成功了呢？我们可以使用下面这个函数来验证。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void glGetShaderiv (GLuint shader, GLenum pname, GLint* params);</span></span></code></pre></div><p>其中，第一个参数 GLuint shader 就是我们要验证的 Shader 句柄；第二个参数 GLenumpname 是我们要验证的这个 Shader 的状态值，我们一般在这里验证是否编译成功，这个状态值选择 GL_COMPILE_STATUS。第三个参数 GLint* params 就是返回值，当返回值是 1 的时候，说明这个 Shader 编译成功了；如果是 0，就说明这个 shader 没有被编译成功。</p><p>这个时候，我们就需要知道着色器代码中的哪一行出了问题，所以还需要开发者再次调用这个函数，只不过是获取这个 Shader 的另外一种状态，这个时候状态值应该选择GL_INFO_LOG_LENGTH，那么返回值返回的就是错误原因字符串的长度，我们可以利用这个长度分配出一个 buffer，然后调用获取出 Shader 的 InfoLog 函数，原型如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void glGetShaderInfoLog(GLuint object, int maxLen, int *len, char *log);</span></span></code></pre></div><p>之后我们可以把 InfoLog 打印出来，帮助我们来调试实际的 Shader 中的错误。按照上面的步骤我们可以创建出 Vertex Shader 和 Fragment Shader，那么接下来我们看图片中的左半部分，也就是如何通过这两个 Shader 来创建 Program。</p><h3 id="创建-program" tabindex="-1">创建 Program <a class="header-anchor" href="#创建-program" aria-label="Permalink to &quot;创建 Program&quot;">​</a></h3><p>首先我们创建一个程序的实例作为程序的容器，这个函数返回程序的句柄。函数原型如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GLuint glCreateProgram(void);</span></span></code></pre></div><p>紧接着将把上面部分编译的 shader 附加（Attach）到刚刚创建的程序中，调用的函数名称如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void glAttachShader(GLuint program, GLuint shader);</span></span></code></pre></div><p>其中，第一个参数 GLuint program 就是传入在上面一步返回的程序容器的句柄，第二个参数GLuint shader 就是编译的 Shader 的句柄，当然要为每一个 shader 都调用一次这个方法才能把两个 Shader 都关联到 Program 中去。</p><p>当顶点着色器和片元着色器都被附加到程序中之后，最后一步就是链接程序，链接函数原型如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void glLinkProgram(GLuint program);</span></span></code></pre></div><p>传入参数就是程序容器的句柄，那么具体这个程序到底有没有链接成功呢？OpenGL 也提供了一个函数用来检查这个程序的状态，函数原型如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>glGetProgramiv (GLuint program, GLenum pname, GLint* params);</span></span></code></pre></div><p>第一个参数就是传入程序容器的句柄，第二个参数代表我们要检查这个程序的哪一个状态，这里面我们传入 GL_LINK_STATUS，最后一个参数就是返回值。返回值是 1 则代表链接成功，如果返回值是 0 则代表链接失败。类似于编译 Shader 的操作，如果链接失败了，可以获取错误信息，以便修改程序。</p><p>获取错误信息时，也得先调用这个函数，但是第二个参数我们传递的是GL_INFO_LOG_LENGTH，代表获取出这个程序的 InfoLog 的长度，拿到长度之后我们分配出一个 char* 的内存空间以获取出 InfoLog，函数原型如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void glGetProgramInfoLog(GLuint object, int maxLen, int *len, char *log);</span></span></code></pre></div><p>调用这个函数返回的 InfoLog，可以作为 Log 打印出来，以便定位问题。</p><p>到这里我们就创建出了一个 Program。回顾一下整个过程和 C 语言的编译和链接阶段非常相似，对比构造 OpenGL Program，编译阶段做了编译顶点着色器和片元着色器，并且把两个着色器 Attach 到 Program 中，链接阶段就是链接这个 Program。</p><p>创建显卡执行程序之后就是如何使用这个程序，其实使用这个构建出来的程序也很简单，调用glUseProgram 这个方法即可，然后将一些内存中的数据与指令传递给这个程序，让这个程序运行起来。但是要想完全运行到手机上，还需要为 OpenGL ES 的运行提供一个上下文环境，下节课我们就来学习在两个平台上如何为 OpenGL ES 创建上下文环境，但是你一定要记住我们刚刚创建好的这个 Program，因为在接下来的课程中还会使用到。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>这节课我们从视频渲染的技术选型开始，给你介绍了视频渲染的实现手段和各自的优缺点，然后对 OpenGL ES 概念、用途、操作步骤等有了一个整体的了解。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E7%A7%BB%E5%8A%A8%E7%AB%AF%E9%9F%B3%E8%A7%86%E9%A2%91%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E7%A7%BB%E5%8A%A8%E7%AB%AF%E9%9F%B3%E8%A7%86%E9%A2%91%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/3.png" alt=""></a></p><p>其中我们重点学习了 OpenGL ES 的渲染管线以及渲染管线中留给开发者书写的顶点着色器和片元着色器两个阶段，最后学习使用 OpenGL ES 提供的接口 API 创建了一个显卡可执行程序，但是想让这个程序运行到显卡上，还需要一个 OpenGL ES 的上下文环境，关于构建OpenGL ES 上下文环境的内容，我们会在下一节课中进行实际操作。期待一下吧！</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>学完了 OpenGL ES 基础内容，想必你已经对 OpenGL ES 有了比较深的了解。那我来考考你。OpenGL ES 渲染管线分为哪几个步骤呢？哪些步骤是我们开发者可以自己去完成的？期待在评论区看到你的回答，也欢迎你把这节课分享给需要的朋友。我们下节课再见！</p>`,101)])])}const L=a(s,[["render",t]]);export{c as __pageData,L as default};
